<template>
  <section class="flex flex-col gap-6">
    <CampaignListFilters :params="params" />
    <Card>
      <AppLoader v-if="isLoading" subject="campaigns" variant="inline" />
      <AppError v-else-if="error" :error="error" title="Failed to load campaigns" variant="table" />
      <ResponsiveTable v-else rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead> Name </ResponsiveTableHead>
          <ResponsiveTableHead> Project </ResponsiveTableHead>
          <ResponsiveTableHead> Urgency </ResponsiveTableHead>
          <ResponsiveTableHead> Channel </ResponsiveTableHead>
          <ResponsiveTableHead> Status </ResponsiveTableHead>
          <ResponsiveTableHead class="text-nowrap"> End Date </ResponsiveTableHead>
          <ResponsiveTableHead> Created </ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableEmpty
            v-if="!data || data.items.length === 0"
            :colspan="7"
            :cols="4"
            :cols-sm="4"
            class="text-center"
          >
            <AppEmpty variant="table" subject="campaigns" />
          </ResponsiveTableEmpty>
          <ResponsiveTableRow v-for="campaign in data?.items" :key="campaign.id" :to="getCampaignRowTo(campaign.id)">
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Name">
              {{ campaign.name }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Project">
              {{ campaign.project.name }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Urgency">
              <Badge :variant="getCampaignUrgency(campaign.urgency_level).variant">
                {{ getCampaignUrgency(campaign.urgency_level).label }}
              </Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Channel">
              <Badge variant="default">{{ getChannelStrategy(campaign.channel_strategy).label }}</Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Status">
              <Badge v-if="campaign.is_active" variant="success">Active</Badge>
              <Badge v-else variant="warning">
                Paused{{ campaign.paused_reason ? `: ${getCampaignPauseReason(campaign.paused_reason).label}` : '' }}
              </Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="End Date">
              {{ campaign.end_date ? formatUTCDateString(campaign.end_date, 'MM/dd/yyyy') : '—' }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Created">
              <div class="flex flex-col leading-tight">
                <span>{{ formatDateToFormat(campaign.created_at, 'MM/dd/yyyy') }}</span>
                <span class="text-xs text-muted-foreground">{{ username(campaign.created_by_user) }}</span>
              </div>
            </ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
        <ResponsiveTableFooter
          v-if="!error && !isLoading && data && data.total_count > 0"
          :colspan="6"
          :cols="4"
          :cols-sm="4"
        >
          <AppPagination :page="params.page" :total="data.total_count" :size="params.size" label="campaigns" />
        </ResponsiveTableFooter>
      </ResponsiveTable>
    </Card>
  </section>
</template>

<script setup lang="ts">
import {
  getCampaignList,
  type CampaignSortBy,
  type CampaignUrgency,
  type GetCampaignListResponse,
  type RecruitmentChannelStrategy,
  type SortType,
} from '~/client';
import { getCampaignUrgency } from '~/constants/recruitment/campaignUrgencyConfig';
import { getCampaignPauseReason } from '~/constants/recruitment/campaignPauseReasonConfig';
import { getChannelStrategy } from '~/constants/recruitment/channelStrategyConfig';
import { formatDateToFormat, formatUTCDateString } from '~/utils/formatDateToFormat';

definePageMeta({
  roles: ['admin'],
  backLabel: 'campaigns',
});

useHead({
  title: 'Campaigns',
});

const route = useRoute('recruitment-campaigns');
const { timezone } = useUserRole();

const params = computed(() => {
  const queryParams = {
    ...parsePagination(route.query, { size: 50 }),
    sort_type: (route.query.sort_type as SortType) || 'desc',
    sort_by: (route.query.sort_by as CampaignSortBy) || 'created_at',
    search_query: (route.query.search_query as string) || undefined,
    project_id: (route.query.project_id as string) || undefined,
    is_active: parseBooleanQuery(route.query.is_active as string),
    urgency_levels: processArrayQueryParameterFromUrl<CampaignUrgency>(route.query.urgency_levels),
    channel_strategies: processArrayQueryParameterFromUrl<RecruitmentChannelStrategy>(route.query.channel_strategies),
    created_at_from: (route.query.created_at_from as string) || undefined,
    created_at_to: (route.query.created_at_to as string) || undefined,
    timezone: timezone.value,
  };

  return Object.fromEntries(
    Object.entries(queryParams).filter(([_, value]) => value !== undefined)
  ) as typeof queryParams;
});

const { data, error, isLoading } = useQuery({
  key: () => ['recruitment-campaigns.list', params.value],
  query: (): Promise<GetCampaignListResponse> => getCampaignList({ composable: '$fetch', query: ref(params.value) }),
  staleTime: 0,
});

function getCampaignRowTo(id: string) {
  return { name: 'recruitment-campaigns-id', params: { id } } as const;
}
</script>
